('sahih-al-bukhari',24,12,'11',NULL,NULL,NULL,NULL,'باب'),
('sahih-al-bukhari',24,13,'12',NULL,NULL,NULL,'To give in charity openly','بَابُ صَدَقَةِ الْعَلاَنِيَةِ'),
('sahih-al-bukhari',24,14,'13',NULL,NULL,NULL,'To give in charity secretly','بَابُ صَدَقَةِ السِّرِّ'),
('sahih-al-bukhari',24,15,'14',NULL,NULL,NULL,'If one gives an object of charity to a wealthy person unknowingly','باب إِذَا تَصَدَّقَ عَلَى غَنِيٍّ وَهُوَ لاَ يَعْلَمُ'),
('sahih-al-bukhari',24,16,'15',NULL,NULL,NULL,'If a person gives something in charity to his own son unknowingly','باب إِذَا تَصَدَّقَ عَلَى ابْنِهِ وَهُوَ لاَ يَشْعُرُ'),
('sahih-al-bukhari',24,17,'16',NULL,NULL,NULL,'To give objects of charity with the right hand','باب الصَّدَقَةِ بِالْيَمِينِ'),
('sahih-al-bukhari',24,18,'17',NULL,NULL,NULL,'Whoever ordered his servant to give something in charity and did not give it himself','باب مَنْ أَمَرَ خَادِمَهُ بِالصَّدَقَةِ وَلَمْ يُنَاوِلْ بِنَفْسِهِ'),
('sahih-al-bukhari',24,19,'18',NULL,NULL,NULL,'The wealthy only are required to give in charity','باب لاَ صَدَقَةَ إِلاَّ عَنْ ظَهْرِ غِنًى'),
