('sahih-al-bukhari',79,37,'37',NULL,NULL,NULL,'The bed.','باب السَّرِيرِ'),
('sahih-al-bukhari',79,38,'38',NULL,NULL,NULL,'Anyone for whom a cushion was put','باب مَنْ أُلْقِيَ لَهُ وِسَادَةٌ'),
('sahih-al-bukhari',79,39,'39',NULL,NULL,NULL,'After Al-Jumu''ah (prayer)','باب الْقَائِلَةِ بَعْدَ الْجُمُعَةَ'),
('sahih-al-bukhari',79,40,'40',NULL,NULL,NULL,'Mid-day nap in the  Mosque','باب الْقَائِلَةِ فِي الْمَسْجِدِ'),
('sahih-al-bukhari',79,41,'41',NULL,NULL,NULL,'Whoever visited some people and had a mid-day nap','باب مَنْ زَارَ قَوْمًا فَقَالَ عِنْدَهُمْ'),
('sahih-al-bukhari',79,42,'42',NULL,NULL,NULL,'Sitting in any convenient position','باب الْجُلُوسِ كَيْفَمَا تَيَسَّرَ'),
