('sahih-al-bukhari',93,50,'50',NULL,NULL,NULL,'Whoever violates a Bai''a','باب مَنْ نَكَثَ بَيْعَةً'),
('sahih-al-bukhari',93,51,'51',NULL,NULL,NULL,'The appointment of a caliph','باب الاِسْتِخْلاَفِ'),
('sahih-al-bukhari',93,52,'51',NULL,NULL,NULL,NULL,'باب'),
('sahih-al-bukhari',93,53,'52',NULL,NULL,NULL,'The expulsion of quarrelsome people from houses','باب إِخْرَاجِ الْخُصُومِ وَأَهْلِ الرِّيَبِ مِنَ الْبُيُوتِ بَعْدَ الْمَعْرِفَةِ'),
