('sahih-muslim',2,16,'16',NULL,NULL,NULL,'The characteristics of the fitrah','باب خِصَالِ الْفِطْرَةِ ‏‏'),
('sahih-muslim',2,17,'17',NULL,NULL,NULL,'Cleaning oneself after relieving oneself','باب الاِسْتِطَابَةِ ‏‏'),
('sahih-muslim',2,18,'18',NULL,NULL,NULL,'The prohibition of cleaning oneself with the right hand','باب النَّهْىِ عَنْ الاِسْتِنْجَاءِ، بِالْيَمِينِ ‏‏'),
('sahih-muslim',2,19,'19',NULL,NULL,NULL,'Starting on the right when purifying oneself and in other matters','باب التَّيَمُّنِ فِي الطُّهُورِ وَغَيْرِهِ ‏‏'),
('sahih-muslim',2,20,'20',NULL,NULL,NULL,'The prohibition of relieving oneself in the street or in the shade','باب النَّهْىِ عَنِ التَّخَلِّي، فِي الطُّرُقِ وَالظِّلاَلِ ‏‏'),
('sahih-muslim',2,21,'21',NULL,NULL,NULL,'Cleaning oneself with water after defecating','باب الاِسْتِنْجَاءِ بِالْمَاءِ مِنَ التَّبَرُّزِ ‏‏'),
