('sahih-muslim',25,4,'4',NULL,NULL,NULL,'Waqf (Endowment)','باب الْوَقْفِ ‏‏'),
('sahih-muslim',25,5,'5',NULL,NULL,NULL,'Not Making A Will For One Who Has Nothing To Be Bequeathed','باب تَرْكِ الْوَصِيَّةِ لِمَنْ لَيْسَ لَهُ شَىْءٌ يُوصِي فِيهِ ‏‏'),
('sahih-muslim',26,1,'1',NULL,NULL,NULL,'The Command To Fulfill Vows','باب الأَمْرِ بِقَضَاءِ النَّذْرِ ‏‏'),
